const fs = require('fs');
const path = require('path');

// ============================================================
// generar_454_tips_viaje.js
// ============================================================
// Dos temas nuevos: que hacer cuando la persona viaja.
//
//   Tú: viaje
//   Chiqui: ¿Viajas con él, o se queda en casa?
//           [Viajo con él en auto] [Se queda en casa]
//
// SE QUEDA EN CASA (4 consejos)
//   · Alguien de confianza que lo visite al menos una vez al dia.
//   · Una prenda con tu olor y sus juguetes favoritos.
//   · Asegurar ventanas y lugares peligrosos.
//   · El comedero automatico ayuda pero no reemplaza a alguien que lo
//     vea: si se enferma o se atasca algo, nadie se entera.
//
// VIAJA EN AUTO (5 consejos)
//   · Nunca suelto: transportin firme o arnes anclado al cinturon.
//   · Sin comida 3 o 4 horas antes.
//   · Parar cada 2 horas.
//   · Auto fresco, sin sacar la cabeza por la ventana.
//   · NUNCA solo dentro del auto cerrado: en minutos la temperatura
//     sube lo suficiente para matarlo.
//
// TAMBIEN SE ARREGLA UNA COSA
// "¿algo mas?" y "¿otra cosa?" no continuaban la conversacion: solo
// funcionaba "¿y que mas?", porque mi regla exigia que empezara con
// "y". Ahora hay una lista de formas de pedir continuar, y un tema
// nuevo sigue ganandole al anterior.
//
// PENDIENTE: que el veterinario de la familia revise estos consejos.
//
// Si algo no calza, ABORTA sin escribir.
// ============================================================

const RUTA = 'components/ChiquiChat.tsx';
const CHAT_B64 = '';

function abortar(motivo) {
  console.log('');
  console.log('ABORTADO: ' + motivo);
  console.log('No se modifico ningun archivo. Avisale a Claude lo que dice este mensaje.');
  process.exit(1);
}

const destino = path.join(process.cwd(), RUTA);
if (!fs.existsSync(destino)) {
  abortar('no se encontro ' + RUTA + '. Corre primero el script 453.');
}

const actual = fs.readFileSync(destino, 'utf8');
if (actual.includes("tema: 'viaje_auto'")) {
  abortar('los tips de viaje ya estan. Parece que este script ya se corrio.');
}
if (!actual.includes("case 'visitas'")) {
  abortar('falta el script 453. Correlo primero.');
}

const comp = Buffer.from(CHAT_B64, 'base64').toString('utf8');

const REQUERIDOS = [
  "'use client'",
  'export default function ChiquiChat',
  "tema: 'viaje_casa'",
  "tema: 'viaje_auto'",
  '¿Viajas con él, o se queda en casa?',
  'transportín firme',
  'Nunca lo dejes solo dentro del auto cerrado',
  'esContinuacion',
  'const EMERGENCIAS',
  "case 'visitas'",
];
for (const r of REQUERIDOS) {
  if (!comp.includes(r)) {
    abortar('el contenido nuevo no incluye [' + r + ']. Script corrupto, no se escribio nada.');
  }
}
if (comp.split('type Tema =').length - 1 !== 1) {
  abortar('type Tema deberia declararse una sola vez.');
}
console.log('  OK  los dos temas de viaje estan');

fs.writeFileSync(destino, comp, 'utf8');
console.log('');
console.log('OK: ' + RUTA);
console.log('');
console.log('Listo. Ya puede aconsejar sobre viajes, con o sin la mascota.');
